//! `ssh-keygen -F`, `-R` and `-H` on known_hosts files, compared against
//! OpenSSH. Every case passes `-f`, so the user's own known_hosts is never
//! touched.

use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::Path;

use sshutils_testing::{Comparison, Differential, Openssh, command, require_openssh, run};
use tempfile::TempDir;

const OURS: &str = env!("CARGO_BIN_EXE_ssh-keygen");

fn keygen(openssh: &Openssh) -> Differential {
    Differential::new(OURS, openssh.require_tool("ssh-keygen"))
}

/// known_hosts files built from keys generated by OpenSSH:
///
/// - `valid`: plain names, ports, wildcards, negation, markers, comments
/// - `invalid`: `valid` plus a malformed line
/// - `hashed`: `valid` hashed by OpenSSH
/// - `simple`: one line with two names, mode 0640
/// - `link`: a symlink to `simple`
fn fixtures(openssh: &Openssh) -> TempDir {
    let dir = tempfile::tempdir().unwrap();
    let d = dir.path();
    let keygen = |args: &[&str]| {
        let out = run(
            command(openssh.require_tool("ssh-keygen"), d).args(args),
            b"",
        );
        assert_eq!(out.status, Some(0), "{args:?}: {}", out.stderr);
    };
    keygen(&["-q", "-t", "ed25519", "-N", "", "-f", "a"]);
    keygen(&["-q", "-t", "rsa", "-b", "1024", "-N", "", "-f", "b"]);
    keygen(&["-q", "-t", "ecdsa", "-N", "", "-f", "c"]);
    let key = |name: &str| {
        let line = fs::read_to_string(d.join(format!("{name}.pub"))).unwrap();
        line.split_whitespace()
            .take(2)
            .collect::<Vec<_>>()
            .join(" ")
    };
    let (a, b, c) = (key("a"), key("b"), key("c"));
    let valid = format!(
        "# a comment line\n\
         host1,host2 {a}\n\
         host1 {b}\n\
         [host1]:2222 {a}\n\
         *.example.com {c}\n\
         !bad.example.com,*.example.com {a}\n\
         10.0.0.? {b}\n\
         @cert-authority *.ca.org {c}\n\
         @revoked host1 {c}\n\
         host3\t{a}   trailing comment\n\
         \n\
         MiXed {b}\n"
    );
    fs::write(d.join("valid"), &valid).unwrap();
    fs::write(d.join("invalid"), format!("{valid}garbage\n")).unwrap();
    fs::write(d.join("hashed"), &valid).unwrap();
    keygen(&["-q", "-H", "-f", "hashed"]);
    fs::remove_file(d.join("hashed.old")).unwrap();
    fs::write(d.join("simple"), format!("one,two {a}\nthree {b}")).unwrap();
    fs::set_permissions(d.join("simple"), fs::Permissions::from_mode(0o640)).unwrap();
    std::os::unix::fs::symlink("simple", d.join("link")).unwrap();
    for key in ["a", "a.pub", "b", "b.pub", "c", "c.pub"] {
        fs::remove_file(d.join(key)).unwrap();
    }
    dir
}

/// Copy every fixture into `dir`, keeping file modes and symlinks.
fn install(fixtures: &Path, dir: &Path) {
    for entry in fs::read_dir(fixtures).unwrap() {
        let entry = entry.unwrap();
        let target = dir.join(entry.file_name());
        if entry.file_type().unwrap().is_symlink() {
            std::os::unix::fs::symlink(fs::read_link(entry.path()).unwrap(), target).unwrap();
        } else {
            fs::copy(entry.path(), target).unwrap();
        }
    }
}

const HOSTS: &[&str] = &[
    "host1",
    "host2",
    "HOST1",
    "[host1]:2222",
    "host1:2222",
    "www.example.com",
    "bad.example.com",
    "10.0.0.5",
    "x.ca.org",
    "host3",
    "mixed",
    "MiXed",
    "nothere",
];

/// File mode (without following symlinks), or `None` if missing.
fn mode(path: impl AsRef<Path>) -> Option<u32> {
    fs::symlink_metadata(path)
        .ok()
        .map(|m| m.permissions().mode() & 0o7777)
}

/// Same outcome, same resulting files (contents and modes).
fn assert_same_result(c: &Comparison, file: &str) {
    c.assert_same_outcome();
    c.assert_same_file(file);
    let old = format!("{file}.old");
    c.assert_same_file(&old);
    for name in [file, old.as_str()] {
        let (ours, theirs) = (c.ours.path(name), c.theirs.path(name));
        assert_eq!(mode(&ours), mode(&theirs), "{name} after {:?}", c.args);
        assert_eq!(
            ours.is_symlink(),
            theirs.is_symlink(),
            "{name} after {:?}",
            c.args
        );
    }
}

#[test]
fn find_host() {
    let openssh = require_openssh!();
    let fixtures = fixtures(&openssh);
    let keygen = keygen(&openssh);
    for file in ["valid", "invalid", "hashed", "missing"] {
        for host in HOSTS {
            for flags in [&[][..], &["-l"], &["-lv"], &["-l", "-E", "md5"]] {
                let mut args = vec!["-F", host];
                args.extend_from_slice(flags);
                args.extend(["-f", file]);
                keygen
                    .case(&args)
                    .setup(|dir| install(fixtures.path(), dir))
                    .run()
                    .assert_same_outcome();
            }
        }
    }
}

#[test]
fn find_host_hashed_output() {
    let openssh = require_openssh!();
    let fixtures = fixtures(&openssh);
    for host in ["host1", "host2", "www.example.com", "x.ca.org", "nothere"] {
        let c = keygen(&openssh)
            .case(["-F", host, "-H", "-f", "valid"])
            .setup(|dir| install(fixtures.path(), dir))
            .run();
        let (ours, theirs) = (&c.ours.outcome, &c.theirs.outcome);
        assert_eq!(ours.status, theirs.status, "{host}");
        assert_eq!(
            mask_hashes(&ours.stdout),
            mask_hashes(&theirs.stdout),
            "{host}"
        );
    }
}

#[test]
fn remove_host() {
    let openssh = require_openssh!();
    let fixtures = fixtures(&openssh);
    let keygen = keygen(&openssh);
    for file in ["valid", "invalid", "hashed", "simple", "link", "missing"] {
        for host in HOSTS.iter().chain(&["one", "two", "three"]) {
            let c = keygen
                .case(["-R", host, "-f", file])
                .setup(|dir| install(fixtures.path(), dir))
                .run();
            assert_same_result(&c, file);
        }
    }
}

/// Replace the random parts of hashed host names.
fn mask_hashes(text: &str) -> String {
    text.lines()
        .map(|line| match line.strip_prefix("|1|") {
            Some(rest) => format!("|1|<hash> {}", rest.split_once(' ').map_or("", |(_, r)| r)),
            None => line.to_string(),
        })
        .collect::<Vec<_>>()
        .join("\n")
}

#[test]
fn hash_known_hosts() {
    let openssh = require_openssh!();
    let fixtures = fixtures(&openssh);
    for file in ["valid", "invalid", "hashed", "simple", "link", "missing"] {
        let c = keygen(&openssh)
            .case(["-H", "-f", file])
            .setup(|dir| install(fixtures.path(), dir))
            .run();
        c.assert_same_outcome();
        c.assert_same_file(format!("{file}.old"));
        let read = |run: &sshutils_testing::Run| fs::read_to_string(run.path(file)).ok();
        assert_eq!(
            read(&c.ours).map(|t| mask_hashes(&t)),
            read(&c.theirs).map(|t| mask_hashes(&t)),
            "{file}"
        );
        assert_eq!(mode(c.ours.path(file)), mode(c.theirs.path(file)), "{file}");

        // OpenSSH must find every host in our hashed file exactly as in its own.
        for host in HOSTS {
            let lookup = |dir: &Path| {
                run(
                    command(openssh.require_tool("ssh-keygen"), dir).args(["-F", host, "-f", file]),
                    b"",
                )
            };
            let (ours, theirs) = (lookup(c.ours.dir.path()), lookup(c.theirs.dir.path()));
            assert_eq!(ours.status, theirs.status, "{file}: {host}");
            assert_eq!(
                mask_hashes(&ours.stdout),
                mask_hashes(&theirs.stdout),
                "{file}: {host}"
            );
        }
    }
}
